import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var tone = React.useState('success'), size = React.useState('md'), solid = React.useState(false), dot = React.useState(true), icon = React.useState(false), text = React.useState('Движение');
    return <div className="dslozenge-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'grid'}>
    <S.DsField id={'lozenge-text'} label={'Текст'} value={text[0]} onChange={function (e) { text[1](e.target.value); }} width={'100%'}/>
    <S.DsField id={'lozenge-tone'} label={'Тон'} as={'select'} value={tone[0]} options={[{ value: 'neutral', label: 'Нейтральный' }, { value: 'info', label: 'Информация' }, { value: 'success', label: 'Успех' }, { value: 'warning', label: 'Предупреждение' }, { value: 'danger', label: 'Ошибка' }]} onChange={function (e) { tone[1](e.target.value); }} width={'100%'}/>
    <S.DsField id={'lozenge-size'} label={'Размер'} as={'select'} value={size[0]} options={[{ value: 'sm', label: 'Маленький — sm' }, { value: 'md', label: 'Обычный — md' }]} onChange={function (e) { size[1](e.target.value); }} width={'100%'}/>
    </div>
    <div className={'row'}>
    <S.DsSwitch label={'Сплошная заливка'} checked={solid[0]} onChange={function (e) { solid[1](e.target.checked); }}/>
    <S.DsSwitch label={'Точка'} checked={dot[0]} onChange={function (e) { dot[1](e.target.checked); }}/>
    <S.DsSwitch label={'Иконка'} checked={icon[0]} onChange={function (e) { icon[1](e.target.checked); }}/>
    </div>
    <div className={'result'}>
    <span className={'cap'}>
    {'Результат'}
    </span>
    <div aria-live={'polite'} aria-atomic={'true'} data-demo={'lozenge-result'}>
    <S.DsLozenge tone={tone[0]} size={size[0]} solid={solid[0]} dot={dot[0]} icon={icon[0] ? 'info' : undefined}>
    {text[0]}
    </S.DsLozenge>
    </div>
    </div>
    </div>
    </div>;
}

